/* ---- 1. the forced-optimum battery: exact answer + the numpy oracle ---- */
for (const s of SYSTEMS) {
    const m = new LinearRegression().fit(s.X, s.y);
    const got = m.coef.concat([m.intercept]);
    let worst = 0, worstOracle = 0;
    for (let j = 0; j < got.length; j++) {
        worst = Math.max(worst, relerr(got[j], s.want[j]));
        worstOracle = Math.max(worstOracle, relerr(got[j], s.oracle[j]));
    }
    assert(worst <= 1e-9,
        s.name + " (" + s.note + "): exact OLS to <= 1e-9 relative, got " +
        worst.toExponential(3) + " coef=" + JSON.stringify(got) +
        " want=" + JSON.stringify(s.want));
    assert(worstOracle <= 1e-9,
        s.name + ": within 1e-9 relative of the numpy lstsq oracle, got " +
        worstOracle.toExponential(3));
    /* the forced optimum is also EXACT on the predictions */
    const pred = m.predict(s.X);
    for (let i = 0; i < pred.length; i++)
        assert(Math.abs(pred[i] - s.y[i]) <= 1e-6 * Math.max(1, Math.abs(s.y[i])),
            s.name + ": prediction " + i + " recovers the target");
}

/* ---- 2. singular designs: the ridge fallback keeps them solvable ---- */
function singularRow(X, y, probe, wantPred, label) {
    const m = new LinearRegression().fit(X, y);   /* must NOT throw */
    for (const c of m.coef.concat([m.intercept]))
        assert(Number.isFinite(c), label + ": coefficients stay finite");
    const p = m.predict([probe])[0];
    assert(Math.abs(p - wantPred) <= 1e-5 * Math.max(1, Math.abs(wantPred)),
        label + ": the identifiable prediction is recovered, got " + p +
        " want " + wantPred);
}
/* duplicate columns: only the sum is identifiable (2 + -1 = 1) */
singularRow([[1, 1], [2, 2], [3, 3]], [1, 2, 3], [4, 4], 4,
    "duplicate columns");
/* a zero column must come out as exactly 0 */
{
    const m = new LinearRegression().fit([[1, 0], [2, 0], [3, 0]], [2, 4, 6]);
    assert(m.coef[1] === 0, "a zero column is fitted as exactly 0");
    assert(Math.abs(m.coef[0] - 2) <= 1e-5, "the live column is recovered");
}
/* exact integer collinearity (col2 = 2 * col1): only 2*c1 + c2 is identifiable */
singularRow([[1, 2], [2, 4], [3, 6]], [3, 6, 9], [4, 8], 12,
    "integer collinear columns");
/* constant columns are collinear with the intercept */
singularRow([[1, 5], [1, 5], [1, 5]], [2, 2, 2], [1, 5], 2,
    "constant columns");
/* an empty fit refuses cleanly (typed, no crash) */
{
    let threw = false;
    try { new LinearRegression().fit([], []); } catch (e) {
        threw = e instanceof TypeError;
    }
    assert(threw, "an empty fit refuses with TypeError");
}

/* ---- 3. dense == sparse, bit-for-bit, on the new path ---- */
{
    const X = [[1, 0, 2], [0, 3, 0], [4, 0, 5], [1, 1, 0]];
    const y = [7, -2, 11, 4];
    const a = new LinearRegression().fit(X, y);
    const b = new LinearRegression().fit(CSR.fromDense(X), y);
    assert(a.coef.length === b.coef.length &&
           a.coef.every((v, i) => Object.is(v, b.coef[i])) &&
           Object.is(a.intercept, b.intercept),
        "a CSR fit is bit-identical to the dense fit of the same reading");
}

/* ---- 4. the weighted identities on the un-ridged path ---- */
{
    const X = [[1], [2], [3], [4]], y = [1, 2, 3, 10];
    const plain = new LinearRegression().fit(X, y);
    const ones = new LinearRegression().fit(X, y, { sampleWeight: [1, 1, 1, 1] });
    assert(plain.coef.every((v, i) => Object.is(v, ones.coef[i])) &&
           Object.is(plain.intercept, ones.intercept),
        "all-ones weights are BIT-identical to no weights");
    const zeroed = new LinearRegression().fit(X, y, { sampleWeight: [1, 1, 1, 0] });
    const deleted = new LinearRegression().fit([[1], [2], [3]], [1, 2, 3]);
    assert(Math.abs(zeroed.predict([[10]])[0] - deleted.predict([[10]])[0]) <= 1e-7,
        "weight 0 == the row not being there (to ridge/rounding)");
}

/* ---- 5. THE NUMERICALLY-SINGULAR BAND (the k-band matrix) ----
 *
 * An exactly-singular design does NOT always eliminate to an exact zero
 * pivot: any non-dyadic collinearity ratio leaves a rounding-level residue,
 * which an elimination that only refuses zero pivots "solves" into
 * coefficients amplified by 1/residue (1e15..1e31) and predictions that are
 * wrong on a perfectly realizable system. These rows are that band made
 * permanent: every family of exact singularity (a constant column, a column
 * that is a multiple of another, duplicate columns, identical rows, a zero
 * column, a three-column dependence) crossed with dyadic AND non-dyadic
 * ratios, dense and CSR, weighted and not.
 *
 * The coefficients of a singular design are not unique, so what is pinned is
 * what is IDENTIFIABLE: the prediction at a probe row (whose direction lies
 * in the design). `oraclePred`/`oracleCoef` come from numpy.linalg.lstsq, an
 * independent SVD solve; the residual of every `exact` row is zero, so the
 * probe prediction is unique however the minimiser splits the null space.
 *
 * The bounds: the identifiable prediction to 1e-4 relative (the ridge
 * fallback's bias on this battery measured 1e-9 .. 1.5e-5, worst at the
 * most extreme ratio; a garbage 1/residue solve misses by 0.5 relative and
 * by 1e15 in the coefficients), and every coefficient inside 8x the
 * minimum-norm solution's largest -- no amplification. */
for (const b of BAND) {
    const opt = b.w ? { sampleWeight: b.w } : undefined;
    const m = new LinearRegression().fit(b.X, b.y, opt);
    const coef = m.coef.concat([m.intercept]);
    for (let j = 0; j < coef.length; j++)
        assert(Number.isFinite(coef[j]),
            b.name + " (" + b.note + "): coefficient " + j + " is finite, got " + coef[j]);
    const oraMax = Math.max(1, ...b.oracleCoef.map(Math.abs));
    for (let j = 0; j < coef.length; j++)
        assert(Math.abs(coef[j]) <= 8 * oraMax,
            b.name + ": no 1/residue amplification -- |coef[" + j + "]| = " +
            Math.abs(coef[j]).toExponential(3) + " <= 8 x " + oraMax);
    const gotPred = m.predict([b.probe])[0];
    assert(Number.isFinite(gotPred) &&
           Math.abs(gotPred - b.oraclePred) <= 1e-4 * Math.max(1, Math.abs(b.oraclePred)),
        b.name + ": the identifiable prediction is the oracle's, got " + gotPred +
        " want " + b.oraclePred);
    /* the fit reproduces the realizable target of every row */
    if (b.realizable) {
        const tp = m.predict(b.X);
        for (let i = 0; i < tp.length; i++)
            assert(Math.abs(tp[i] - b.y[i]) <= 1e-4 * Math.max(1, Math.abs(b.y[i])),
                b.name + ": training prediction " + i + " recovers the target, got " +
                tp[i] + " want " + b.y[i]);
    }
    /* sparse == dense, BIT-identical, on the fallback path too */
    const s = new LinearRegression().fit(CSR.fromDense(b.X), b.y, opt);
    assert(s.coef.length === m.coef.length &&
           s.coef.every((v, i) => Object.is(v, m.coef[i])) &&
           Object.is(s.intercept, m.intercept),
        b.name + ": a CSR fit is bit-identical to the dense fit");
    assert(Object.is(s.predict([b.probe])[0], gotPred),
        b.name + ": the CSR prediction is bit-identical");
    m.close(); s.close();
}

/* ---- 6. the weight range: no load may overflow or underflow ----
 *
 * The ridge load is DYN_RIDGE x the system scale, and the system is divided
 * by the mean weight BEFORE the load is formed -- so a huge (1e300) or
 * subnormal (1e-320) weight scale cannot turn it into +Inf (whose pivots the
 * elimination refused, leaving no answer) or into 0 (which left a singular
 * system singular and threw "singular system" at a caller whose weights were
 * all equal). Weighted least squares is homogeneous in the weights, so these
 * rows also pin the answer against the unit-weight fit. */
{
    const X = [[1, 1], [2, 2], [3, 3]], y = [1, 2, 3], probe = [4, 4];
    const unit = new LinearRegression().fit(X, y);
    const unitPred = unit.predict([probe])[0];
    assert(Math.abs(unitPred - 4) <= 1e-4, "the unit-weight reference prediction");
    /* 2^1000: a power-of-two scale, so dividing by the mean weight is exact
       and the fit must be BIT-identical to the unit-weight one */
    const pow2 = new LinearRegression().fit(X, y, { sampleWeight: [Math.pow(2, 1000), Math.pow(2, 1000), Math.pow(2, 1000)] });
    assert(Number.isFinite(pow2.coef[0]) && Number.isFinite(pow2.intercept),
        "weights 2^1000: finite coefficients");
    assert(pow2.coef.every((v, i) => Object.is(v, unit.coef[i])) &&
           Object.is(pow2.intercept, unit.intercept),
        "weights 2^1000 are bit-identical to unit weights (exact power-of-two scale)");
    /* 1e300: used to overflow the load into +Inf -> no usable answer */
    const huge = new LinearRegression().fit(X, y, { sampleWeight: [1e300, 1e300, 1e300] });
    const hugeCoef = huge.coef.concat([huge.intercept]);
    assert(hugeCoef.every(Number.isFinite), "weights 1e300: finite coefficients, got " + JSON.stringify(hugeCoef));
    assert(Math.max(...hugeCoef.map(Math.abs)) > 0.5,
        "weights 1e300: NOT the silently-zero model, got " + JSON.stringify(hugeCoef));
    assert(Math.abs(huge.predict([probe])[0] - unitPred) <= 1e-6 * Math.max(1, Math.abs(unitPred)),
        "weights 1e300: the identifiable prediction matches the unit-weight fit, got " +
        huge.predict([probe])[0]);
    /* 1e-320 (subnormal): used to underflow the load to 0 -> "singular system" */
    const tiny = new LinearRegression().fit(X, y, { sampleWeight: [1e-320, 1e-320, 1e-320] });
    assert(tiny.coef.concat([tiny.intercept]).every(Number.isFinite),
        "subnormal weights: finite coefficients");
    assert(Math.abs(tiny.predict([probe])[0] - unitPred) <= 1e-6 * Math.max(1, Math.abs(unitPred)),
        "subnormal weights: the identifiable prediction matches the unit-weight fit");
    /* subnormal weights beside a ZERO column: the ridge underflowed to 0 and
       the fit threw "singular system"; the least-squares answer is the mean */
    const zx = new LinearRegression().fit([[0], [0]], [1, 2], { sampleWeight: [1e-320, 1e-320] });
    assert(zx.coef.concat([zx.intercept]).every(Number.isFinite),
        "subnormal weights + zero column: finite, got " + JSON.stringify(zx.coef));
    assert(Math.abs(zx.predict([[0]])[0] - 1.5) <= 1e-6,
        "subnormal weights + zero column: the least-squares intercept is the mean, got " +
        zx.predict([[0]])[0]);
    /* a mixed subnormal/normal weight vector keeps the homogeneity */
    const mixed = new LinearRegression().fit(X, y, { sampleWeight: [1e-320, 1, 1] });
    assert(mixed.coef.concat([mixed.intercept]).every(Number.isFinite),
        "mixed subnormal weights: finite coefficients");
    unit.close(); pow2.close(); huge.close(); tiny.close(); zx.close(); mixed.close();
    /* the stated finite-input LIMIT at the top of the range: A^T A is
       accumulated from the raw weight x feature^2 products BEFORE the weight
       normalization runs, so a product past ~1.8e308 (1e300 weights on
       1e6-scale features) reaches the solve as +Inf, where no load can repair
       it. The fit refuses with the typed InternalError instead of returning a
       model -- pinned here so the boundary stays a documented refusal, not a
       silent regression. */
    let overflowThrew = null;
    try {
        new LinearRegression().fit([[1, 1e6], [2, 1e6], [3, 1e6], [4, 1e6]],
            [3, 5, 7, 9], { sampleWeight: [1e300, 1e300, 1e300, 1e300] });
    } catch (e) {
        overflowThrew = e;
    }
    assert(overflowThrew !== null &&
           /singular system/.test(overflowThrew.message),
        "1e300 weights on 1e6-scale features: the documented overflow limit " +
        "refuses with 'singular system', got " + overflowThrew);
}

/* ---- 7. THE CONDITIONING GATE: near-singular WELL-POSED designs and
 *          mixed-unit singular scales (the generated NEAR block) ----
 *
 * The gate (DYN_SOLVE_MIN_PIVOT = 1000*eps ~ 2.2e-13 relative) has to split
 * two regimes the elimination cannot tell apart -- both end in a tiny last
 * pivot:
 *   - side "exact": the pivot is a genuine small singular value. The design
 *     is WELL-POSED however near-singular, and the un-ridged solve must
 *     deliver the exact OLS answer: predictions on the training rows AND an
 *     out-of-row probe to <= 1e-12 relative, coefficients to <= 1e-6 (the
 *     near-null coefficient component carries the conditioning noise; the
 *     predictions do not). The null-heavy targets are the sharp end of this:
 *     y = -d*z IS 3*x1 - x2, so their true coefficients (3, -1, 0) lie ALONG
 *     the near-null direction -- exactly what a ridge bias shrinks (the old
 *     2.2e-7 gate routed these rows to a ridge whose SCALE-PROPORTIONAL load
 *     missed by up to 1.3e0 relative; measured under the current absolute
 *     load the same misrouting still costs ~6e-10, 600x over the bound).
 *   - side "ridge": the pivot sits in the elimination's rounding band --
 *     genuine rank deficiency. Only identifiable quantities are pinned, at
 *     <= 1e-6 (the fallback's measured error here is ~1e-10; a garbage
 *     1/residue solve misses by 1e15). The mixed-unit rows (exactly singular
 *     at EVERY magnitude: the elimination leaves an exact zero pivot, so no
 *     positive gate can keep them off the ridge) are what pins the LOAD: the
 *     ridge is 1e-9 x the mean weight and nothing else -- a load proportional
 *     to the system's own largest diagonal grows with the constant column's
 *     units and zeroes the unit-scale direction (measured: 3.2e-2 relative
 *     error at 1e4, the zero model at 1e6).
 *
 * `ratio`/`side` are computed by the generator replicating the C elimination
 * op-for-op, so each row asserts the ROUTING it must take, not merely a
 * bound.
 *
 * MUTATION MATRIX -- each row below fails under exactly one of these single
 * constant flips (and passes the other two):
 *   - gate back to eps/DYN_RIDGE (2.2e-7): every side "exact" row is
 *     ridge-routed instead and fails its 1e-12 bound;
 *   - gate to 1e-300: the non-dyadic BAND rows (section 5) solve their
 *     rounding residue un-ridged into 1/residue garbage -- the amplification
 *     assertions there fail;
 *   - ridge load back to DYN_RIDGE x system scale: every side "ridge" row and
 *     the mixed-unit rows collapse toward the null direction (and the
 *     1e-320/1e300 weight corners of section 6 throw instead). */
for (const nr of NEAR) {
    const bound = nr.side === "exact" ? 1e-12 : 1e-6;
    const m = new LinearRegression().fit(nr.X, nr.y);   /* must NOT throw */
    const coef = m.coef.concat([m.intercept]);
    for (let j = 0; j < coef.length; j++)
        assert(Number.isFinite(coef[j]),
            nr.name + " (" + nr.note + "): coefficient " + j + " is finite, got " + coef[j]);
    if (!nr.singular) {
        /* well-posed: the OLS answer is UNIQUE, so the coefficients are
           pinnable -- at 1e-6 relative, because the near-null component
           carries the conditioning noise (measured 1.7e-9 at ratio 7.9e-13)
           while every PREDICTION stays exact, which the next assertions pin
           600x tighter */
        let worst = 0, worstOracle = 0;
        for (let j = 0; j < coef.length; j++) {
            worst = Math.max(worst, relerr(coef[j], nr.want[j]));
            worstOracle = Math.max(worstOracle, relerr(coef[j], nr.oracle[j]));
        }
        assert(worst <= 1e-6,
            nr.name + ": coefficients within 1e-6 relative of the exact " +
            "OLS answer, got " + worst.toExponential(3) +
            " coef=" + JSON.stringify(coef) + " want=" + JSON.stringify(nr.want));
        assert(worstOracle <= 1e-6,
            nr.name + ": coefficients within 1e-6 relative of the numpy " +
            "lstsq oracle, got " + worstOracle.toExponential(3));
    } else {
        /* exactly singular: the coefficients are NOT unique -- pin only that
           the fit is a real model, not the silently-zeroed one */
        const mag = coef.reduce((s, v) => s + Math.abs(v), 0);
        assert(mag > 0.5,
            nr.name + ": NOT the silently-zero model, coef=" + JSON.stringify(coef));
    }
    /* every row's target is exactly realizable: training predictions recover
       it, and the probe prediction (whose direction lies in the design) is
       the exact one -- at 1e-12 on the exact side (measured <= 2.7e-15; the
       gate regression measured up to 1.3e0 here) and 1e-6 on the ridge side
       (measured <= 1.1e-10) */
    const tp = m.predict(nr.X);
    for (let i = 0; i < tp.length; i++)
        assert(relerr(tp[i], nr.y[i]) <= bound,
            nr.name + ": training prediction " + i + " within " + bound +
            " relative, got " + tp[i] + " want " + nr.y[i]);
    const pp = m.predict([nr.probe])[0];
    assert(relerr(pp, nr.probeWant) <= bound,
        nr.name + ": probe prediction within " + bound + " relative, got " +
        pp + " want " + nr.probeWant);
    m.close();
}


print("test_ml_linreg_exact: all " + n + " assertions passed");
